// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Integers include positive numbers, negative numbers and zero. Let's master the rules for combining them.","blocks":[{"t":"p","text":"Integers are whole numbers and their opposites: …, −3, −2, −1, 0, 1, 2, 3, … Absolute value is the distance from zero: |−7| = 7."},{"t":"key","text":"Adding: same signs → add and keep the sign; different signs → subtract and keep the sign of the larger absolute value. Subtracting: add the opposite. Multiplying or dividing: same signs → positive; different signs → negative."},{"t":"ex","problem":"Simplify −8 − (−3) + (−4)(2)","steps":["Subtracting −3 means adding 3: −8 + 3 = −5","(−4)(2) = −8","−5 + (−8)"],"answer":"−13"},{"t":"tip","text":"Think of a number line: adding a positive moves right, adding a negative moves left."}]},{"say":"Fractions and decimals are two ways to write parts of a whole. Let's move between them and compute with confidence.","blocks":[{"t":"list","items":["To add or subtract fractions, find a common denominator.","To multiply, multiply tops and bottoms. To divide, multiply by the reciprocal.","To turn a fraction into a decimal, divide: 3/8 = 0.375."]},{"t":"key","text":"Order of operations: Parentheses, Exponents, Multiplication and Division (left to right), Addition and Subtraction (left to right)."},{"t":"ex","problem":"Compute 2/3 + 3/4","steps":["Common denominator 12: 8/12 + 9/12"],"answer":"17/12, or 1 5/12"},{"t":"ex","problem":"Evaluate 4 + 6 × (5 − 3)²","steps":["Parentheses: 2; exponent: 4","6 × 4 = 24; 4 + 24"],"answer":"28"}]}],[{"say":"Ratios compare quantities. They help with recipes, maps, speeds and best buys.","blocks":[{"t":"p","text":"A ratio compares two quantities, written 3:4, 3 to 4, or 3/4. A rate compares quantities with different units, like 60 miles per hour. A unit rate has a denominator of 1."},{"t":"key","text":"A proportion says two ratios are equal. Solve by cross-multiplying: if a/b = c/d, then ad = bc."},{"t":"ex","problem":"4 notebooks cost $10. How much do 7 cost?","steps":["4/10 = 7/x","4x = 70"],"answer":"x = $17.50"},{"t":"p","text":"Unit prices help compare deals: $3.00 for 12 ounces is $0.25 per ounce."}]},{"say":"Percent means \"per hundred.\" Percents show up everywhere: sales, tips, grades and taxes.","blocks":[{"t":"key","text":"Percent of a number: part = percent × whole. Write the percent as a decimal first: 35% = 0.35."},{"t":"list","items":["Discount: subtract the percent from the price. Tax and tip: add it.","Percent change = (new − old) ÷ old × 100%."]},{"t":"ex","problem":"A $60 jacket is 25% off. What's the sale price?","steps":["25% of 60 = 0.25 × 60 = 15","60 − 15"],"answer":"$45"},{"t":"ex","problem":"A price rises from $40 to $50. Percent change?","steps":["(50 − 40) ÷ 40 = 0.25"],"answer":"25% increase"}]}],[{"say":"Algebra uses letters to stand for numbers. Expressions are the building blocks.","blocks":[{"t":"p","text":"A variable is a letter that represents a number. An expression combines numbers, variables and operations, like 3x + 5."},{"t":"key","text":"Combine like terms (terms with the same variable part) and use the distributive property: a(b + c) = ab + ac."},{"t":"ex","problem":"Simplify 4(x + 2) + 3x − 5","steps":["Distribute: 4x + 8 + 3x − 5","Combine: 7x + 3"],"answer":"7x + 3"},{"t":"p","text":"To evaluate an expression, substitute the value: if x = 2, then 7x + 3 = 17."},{"t":"p","text":"Translate words: \"5 more than a number\" is n + 5; \"twice a number\" is 2n; \"3 less than a number\" is n − 3."}]},{"say":"Solving an equation means finding the value that makes it true. Keep it balanced!","blocks":[{"t":"key","text":"Use inverse operations to isolate the variable, doing the same thing to both sides."},{"t":"ex","problem":"Solve 3x − 4 = 11","steps":["Add 4: 3x = 15","Divide by 3"],"answer":"x = 5"},{"t":"p","text":"Inequalities use <, >, ≤, ≥. Solve them like equations, but flip the sign if you multiply or divide by a negative number. Graph solutions on a number line with an open circle (< or >) or closed circle (≤ or ≥)."},{"t":"ex","problem":"Solve −2x > 8","steps":["Divide by −2 and flip"],"answer":"x < −4"}]}],[{"say":"Geometry helps us measure the world: rooms, gardens, pizzas and more.","blocks":[{"t":"key","text":"Perimeter is the distance around a shape. Area is the space inside. Rectangle A = lw; triangle A = ½bh; circle C = 2πr and A = πr²."},{"t":"ex","problem":"A circular garden has a radius of 5 m. Find its area and circumference (use π ≈ 3.14).","steps":["A = 3.14 × 5² = 78.5 m²","C = 2 × 3.14 × 5"],"answer":"78.5 m² and 31.4 m"},{"t":"p","text":"Angles: a straight line is 180°, a right angle is 90°, and a triangle's angles add to 180°."}]},{"say":"Volume measures space inside 3D shapes, and the Pythagorean theorem finds missing sides of right triangles.","blocks":[{"t":"key","text":"Volume of a rectangular prism V = lwh; cylinder V = πr²h. Pythagorean theorem: a² + b² = c² for right triangles, where c is the hypotenuse."},{"t":"ex","problem":"A box is 4 cm by 3 cm by 10 cm. Find its volume.","steps":["V = 4 × 3 × 10"],"answer":"120 cm³"},{"t":"ex","problem":"A right triangle has legs 6 and 8. Find the hypotenuse.","steps":["6² + 8² = 36 + 64 = 100"],"answer":"c = 10"},{"t":"p","text":"Volume is measured in cubic units, area in square units, and length in plain units."}]}],[{"say":"Statistics helps us summarize lots of numbers with just a few. Let's find the center of data.","blocks":[{"t":"key","text":"Mean = sum ÷ count. Median = middle value when sorted. Mode = most common value. Range = max − min."},{"t":"ex","problem":"Find the mean, median and range of 4, 7, 7, 9, 13","steps":["Mean: 40 ÷ 5 = 8","Median: the middle value is 7"],"answer":"mean 8, median 7, mode 7, range 9"},{"t":"p","text":"An outlier (a value far from the others) affects the mean more than the median. Graphs like bar graphs, histograms, line plots and box plots display data."}]},{"say":"Probability measures how likely something is to happen, from 0 (impossible) to 1 (certain).","blocks":[{"t":"key","text":"Probability = favorable outcomes ÷ total possible outcomes."},{"t":"ex","problem":"A bag has 3 red and 5 blue marbles. What's the probability of drawing red?","steps":["3 favorable out of 8 total"],"answer":"3/8"},{"t":"list","items":["Experimental probability comes from actually doing trials; theoretical probability comes from reasoning.","For independent events, multiply probabilities: P(heads and rolling a 6) = 1/2 × 1/6 = 1/12.","A sample space lists all possible outcomes; a tree diagram helps organize them."]}]}]];
export default text;
